"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([["89036"],{9285(e){e.exports=JSON.parse('{"tag":{"label":"sanctuary","permalink":"/docs/tags/sanctuary","allTagsPath":"/docs/tags","count":9,"items":[{"id":"sanctuary/apple","title":"Apple","description":"Apple is HALT Rescue\'s first confirmed satin carrier with osteodystrophy. He is only 8 months old and already showing signs of the painful bone disease associated with the satin coat gene.","permalink":"/docs/sanctuary/apple"},{"id":"sanctuary/gothic","title":"Gothic","description":"Gothic is Hero\'s son and a HALT Rescue sanctuary guinea pig. He is being monitored for inflamed lymph nodes.","permalink":"/docs/sanctuary/gothic"},{"id":"sanctuary/hero","title":"Hero","description":"Hero is a lethal white guinea pig and one of HALT Rescue\'s most beloved sanctuary residents. He\'s approaching his first birthday, loves Phillies games, and has a lot to say.","permalink":"/docs/sanctuary/hero"},{"id":"sanctuary/miles","title":"Miles","description":"Miles is a HALT Rescue sanctuary guinea pig with a more advanced case of osteodystrophy (satin syndrome). Despite his condition, he is full of joy and loves running to the side of his cage to greet visitors.","permalink":"/docs/sanctuary/miles"},{"id":"sanctuary/phoenix","title":"Phoenix","description":"Phoenix is a tiny HALT Rescue sanctuary guinea pig with stunted growth. No cause was found on physical exam, but a possible liver shunt is being investigated.","permalink":"/docs/sanctuary/phoenix"},{"id":"sanctuary/quest","title":"Quest","description":"Quest is a long-term HALT Rescue sanctuary resident with ongoing health management needs. He was once bonded to Quill, but their relationship changed over time as his health evolved.","permalink":"/docs/sanctuary/quest"},{"id":"sanctuary/sonnet","title":"Sonnet","description":"Sonnet is a HALT Rescue sanctuary guinea pig who was spayed for ovarian cysts and cervical hyperplasia. She arrived with severe hormonal hairloss and has made a remarkable recovery.","permalink":"/docs/sanctuary/sonnet"},{"id":"sanctuary/toothless","title":"Toothless","description":"Toothless is a guinea pig who arrived at HALT Rescue in April 2026 after a broken tooth created an abscess on his chin. He had emergency dental surgery and is recovering beautifully.","permalink":"/docs/sanctuary/toothless"},{"id":"sanctuary/valencia","title":"Valencia","description":"Valencia is a HALT Rescue sanctuary guinea pig who requires regular ongoing veterinary care and monitoring.","permalink":"/docs/sanctuary/valencia"}],"unlisted":false}}')}}]);